"""The MHPCO's policy management rules for quoting and claiming."""

PROCESSING_FEE = 5

BASE_PREMIUMS = {"sword": 100}


def run_scenario(scenario):
    """Process a scenario's steps in order and return the corresponding results."""
    return {"results": [quote(step["items"]) for step in scenario["steps"]]}


def quote(items):
    """Report the result of quoting a policy over the given items."""
    return {"premium": premium_for(items)}


def premium_for(items):
    """Compute the premium the MHPCO charges for insuring the given items."""
    return policy_base_premium(items) + PROCESSING_FEE


def policy_base_premium(items):
    """Sum the base premiums the MHPCO's price list assigns to the given items."""
    return sum(BASE_PREMIUMS[item["type"]] for item in items)
